// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { SearchIcon } from 'lucide-react'

import { DemoStage, PanelChrome, type Build } from '@/app/demos/stage'

import { CAPTIONS, CATEGORY_COLOR, QUERIES, RESULTS } from './script'

const FLIPS = '0123456789'

const build: Build = ({ tl, q, qa, step, final, move, click, type, scramble, wait, cursorOut }) => {
  const show = (index: number) => {
    const entry = RESULTS[index][0]
    const digits = String(entry.code).split('')
    const start = tl.duration()
    digits.forEach((digit, slot) => {
      const tile = q(`flap-${slot}`)
      const text = q(`flap-${slot}-text`)
      const rolls = [FLIPS[(Number(digit) + 3 + slot) % 10], FLIPS[(Number(digit) + 7) % 10], digit]
      rolls.forEach((char, roll) => {
        const at = start + slot * 0.08 + roll * 0.16
        tl.to(tile, { rotateX: -90, duration: 0.07, ease: 'power2.in' }, at)
        tl.to(text, { text: { value: char, delimiter: '' }, duration: 0.01 }, at + 0.07)
        tl.to(tile, { rotateX: 0, duration: 0.09, ease: 'power2.out' }, at + 0.08)
      })
    })
    const color = CATEGORY_COLOR[entry.category]
    scramble('name', entry.name, { at: start + 0.1, duration: 0.5 })
    tl.to(
      q('category'),
      { text: { value: entry.category, delimiter: '' }, color, borderColor: color, duration: 0.3 },
      start + 0.2,
    )
    tl.to(qa('flap'), { color, duration: 0.3 }, start + 0.2)
    tl.to(
      q('hint'),
      { text: { value: entry.hint, delimiter: '' }, duration: 0.5, ease: 'none' },
      start + 0.4,
    )
  }
  const search = (index: number) => {
    move('search', { ax: 0.3 })
    click('search')
    if (index > 0) tl.to(q('search-text'), { text: '', duration: 0.15 })
    type('search-text', QUERIES[index], { speed: 0.07 })
    show(index)
  }

  step(0)
  search(0)

  step(1, '+=0.6')
  search(1)

  step(2, '+=0.6')
  search(2)

  step(3, '+=0.6')
  search(3)
  tl.fromTo(
    qa('more'),
    { opacity: 0, y: 10 },
    { opacity: 1, y: 0, duration: 0.3, stagger: 0.07, ease: 'power3.out' },
    '<0.3',
  )
  cursorOut('+=0.3')
  final()
  wait(1.6)
}

export default function Demo() {
  const more = RESULTS[3].slice(1)
  return (
    <DemoStage
      label="HTTP Status reference looking up 404, 200, Service Unavailable and the redirect group"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2.5">
          <div
            data-d="search"
            className="flex h-8 items-center gap-2 rounded-lg border border-line bg-canvas/80 px-2.5 text-[11px]"
          >
            <SearchIcon className="size-3.5 text-muted" />
            <span data-d="search-text" className="demo-caret text-ink" />
          </div>
          <div className="rounded-xl border border-line-strong bg-canvas/70 p-3">
            <div className="flex items-center gap-3">
              <div className="flex gap-1 [perspective:300px]">
                {[0, 1, 2].map((slot) => (
                  <span
                    key={slot}
                    data-d={`flap flap-${slot}`}
                    className="relative flex h-12 w-9 items-center justify-center rounded-md bg-elevated font-mono text-[28px] font-semibold text-ink shadow-[inset_0_-1px_0_rgba(255,255,255,0.06)]"
                  >
                    <span data-d={`flap-${slot}-text`}>0</span>
                    <span className="absolute inset-x-0 top-1/2 h-px bg-black/60" />
                  </span>
                ))}
              </div>
              <div className="min-w-0 flex-1">
                <p data-d="name" className="h-5 truncate text-[14px] font-medium text-ink">
                  &nbsp;
                </p>
                <span
                  data-d="category"
                  className="mt-1 inline-block h-[18px] rounded-full border border-line-strong px-2 text-[9.5px] leading-[16px] text-muted"
                >
                  &nbsp;
                </span>
              </div>
            </div>
            <p data-d="hint" className="mt-2.5 h-4 text-[10.5px] text-ink-soft" />
          </div>
          <div className="space-y-1.5">
            {more.map((entry) => (
              <div
                key={entry.code}
                data-d="more"
                className="flex items-center gap-2 rounded-lg border border-line bg-canvas/60 px-2.5 py-1.5 opacity-0"
              >
                <span className="rounded-md border border-line-strong px-1.5 font-mono text-[10px] text-ink">
                  {entry.code}
                </span>
                <span className="text-[10.5px] font-medium text-ink">{entry.name}</span>
                <span className="ml-auto truncate text-[9.5px] text-muted">{entry.hint}</span>
              </div>
            ))}
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
